import assert from "node:assert/strict"
import { webcrypto } from "node:crypto"
import { readFileSync } from "node:fs"
import ts from "typescript"

globalThis.crypto ??= webcrypto

const source = readFileSync(new URL("../src/lib/striping.ts", import.meta.url), "utf8")
const compiled = ts.transpileModule(source, {
  compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ES2022 },
}).outputText
const { stripeIndexHash, stripeManifestHash, verifyStripeIndex } = await import(`data:text/javascript;base64,${Buffer.from(compiled).toString("base64")}`)

// This vector is generated by app.services.striping.index_hash.
const actual = await stripeIndexHash([
  { size_bytes: 16777216, sha256: "ca978112ca1bbdcafac231b39a23dc4da786eff8147c4e72b9807785afee48bb" },
  { size_bytes: 4, sha256: "3a6eb0790f39ac87c94f3856b2dd2c5d110e6811602261a9a923d3bb23adc8b7" },
])
assert.equal(actual, "e1dfdad3038b56db638cd85822e7c9e15804516e6a737175924c89629268e208")

const chunks = [
  {
    index: 0, chunk_id: "11111111-1111-1111-1111-111111111111",
    connection_id: "aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa", provider: "aws",
    size_bytes: 16777216, sha256: "ca978112ca1bbdcafac231b39a23dc4da786eff8147c4e72b9807785afee48bb",
  },
  {
    index: 1, chunk_id: "22222222-2222-2222-2222-222222222222",
    connection_id: "bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb", provider: "r2",
    size_bytes: 4, sha256: "3a6eb0790f39ac87c94f3856b2dd2c5d110e6811602261a9a923d3bb23adc8b7",
  },
]
const index_hash = "0573ca0e22aada8a822f775b022dabadfcde69c7dca649d8b651707408ffe1f0"
assert.equal(await stripeManifestHash(16777220, chunks), index_hash)
assert.equal(await verifyStripeIndex({ index_version: 2, index_hash, size_bytes: 16777220, chunks }), true)
assert.equal(await verifyStripeIndex({
  index_version: 2, index_hash, size_bytes: 16777220,
  chunks: [{ ...chunks[0], connection_id: chunks[1].connection_id }, chunks[1]],
}), false)
console.log("Stripe v1/v2 indexes match Python vectors; placement tampering is rejected")
